{"hypotheses": [
  {
    "name": "Hypothesis_1",
    "mechanism": "Firms with poor performance but strong market expectations may outperform in bear markets as they are more likely to reverse losses through strategic pivots, cost-cutting, or M&A.",
    "expression": {
      "terms": [{"weight": -1.0, "primitive": "Beta"}, {"weight": 0.5, "primitive": "AnalystRevision"}, {"weight": 0.5, "primitive": "Size"}],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "AnalystRevision", "bound": "above", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.6,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Hypothesis_2",
    "mechanism": "Firms with high R&D expense and low market expectations have potential to outperform due to undervalued innovation.",
    "expression": {
      "terms": [{"weight": 1.0, "primitive": "RD"}, {"weight": -0.5, "primitive": "AnalystRevision"}],
      "regime": null,
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "correlation", "primitive": "RD", "bound": "above", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": null
  },
  {
    "name": "Hypothesis_3",
    "mechanism": "Firms with low book-to-market ratio but high leverage are undervalued and may outperform as they can utilize debt effectively.",
    "expression": {
      "terms": [{"weight": -1.0, "primitive": "BM"}, {"weight": 1.0, "primitive": "Leverage"}],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "international", "region": "emerging", "direction": "same_sign"},
      {"type": "correlation", "primitive": "BM", "bound": "below", "threshold": 0.3}
