      "terms": [{"weight": 1.0, "primitive": "EarningsSurprise"}, {"weight": -1.0, "primitive": "AOP"}],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "correlation", "primitive": "AOP", "bound": "below", "threshold": 0.3}
