    "expected_annualized_sharpe": 0.6,
    "expected_decay_half_life_months": 60
  },
  {
    "name": "Hypothesis_5",
    "mechanism": "Firms with high short interest and low price may outperform due to the potential for a short squeeze.",
    "expression": {
      "terms": [{"weight": 1.0, "primitive": "ShortInterest"}, {"weight": -1.0, "primitive": "Price"}],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": false
